import pathlib,tempfile,inspect
from ken._paths import resolve_project_path as f
assert inspect.signature(f).parameters['must_exist'].kind==inspect.Parameter.KEYWORD_ONLY
with tempfile.TemporaryDirectory() as d:
 r=pathlib.Path(d).resolve();(r/'f').touch();(r/'dir').mkdir()
 for x in ('f','dir'): assert f(r,x,must_exist=True)==r/x
 assert f(r,'missing')==r/'missing'
 try:f(r,'missing',must_exist=True)
 except FileNotFoundError:pass
 else:raise AssertionError('missing accepted')
 try:f(r,'../escape-nonexistent',must_exist=True)
 except ValueError:pass
 else:raise AssertionError('escape accepted')
